#!/usr/bin/python3
# SPDX-License-Identifier: GPL-3.0-or-later

"""Build OSTree-bound UKIs from the GRUB menu generated by Deepin."""

from __future__ import annotations

import argparse
import fcntl
import hashlib
import os
import re
import shlex
import shutil
import subprocess
import sys
import tempfile
from dataclasses import dataclass
from pathlib import Path


class ManagerError(RuntimeError):
    pass


class TransactionRecoveryError(ManagerError):
    """A pair publication failed and its recovery files must be preserved."""


@dataclass(frozen=True)
class BootEntry:
    title: str
    kernel: str
    initrds: tuple[str, ...]
    cmdline: str
    ostree: str

    @property
    def deployment_id(self) -> str:
        match = re.search(r"/([^/]+)/checkout/?$", self.ostree)
        if match:
            return match.group(1)
        match = re.match(r"/boot/immutable/([^/]+)/", self.kernel)
        if match:
            return match.group(1)
        return hashlib.sha256(self.ostree.encode()).hexdigest()[:16]


def _code_and_brace_delta(line: str) -> tuple[str, int]:
    """Remove GRUB comments and count braces outside strings."""
    out: list[str] = []
    quote: str | None = None
    escaped = False
    delta = 0
    for char in line:
        if escaped:
            out.append(char)
            escaped = False
            continue
        if char == "\\":
            out.append(char)
            escaped = True
            continue
        if quote:
            out.append(char)
            if char == quote:
                quote = None
            continue
        if char in ("'", '"'):
            quote = char
            out.append(char)
        elif char == "#":
            break
        elif char == "{":
            delta += 1
            out.append(char)
        elif char == "}":
            delta -= 1
            out.append(char)
        else:
            out.append(char)
    return "".join(out), delta


def parse_top_level_entries(
    config: str, auto_deployments: list[str] | None = None
) -> list[BootEntry]:
    """Parse top-level menuentry blocks, intentionally ignoring submenus."""
    blocks: list[tuple[str, list[str]]] = []
    depth = 0
    current_title: str | None = None
    current_lines: list[str] = []

    for line in config.splitlines():
        code, delta = _code_and_brace_delta(line)
        if current_title is None and depth == 0:
            match = re.match(r"\s*menuentry\s+(['\"])(.*?)\1", code)
            if match:
                current_title = match.group(2)
                current_lines = [line]
                depth += delta
                if delta <= 0 and depth == 0:
                    blocks.append((current_title, current_lines))
                    current_title = None
                continue
        elif current_title is not None:
            current_lines.append(line)
            depth += delta
            if depth == 0:
                blocks.append((current_title, current_lines))
                current_title = None
                current_lines = []
            continue
        depth += delta

    entries: list[BootEntry] = []
    auto_deployment_ids = iter(auto_deployments or [])
    for title, lines in blocks:
        linux_args: list[str] | None = None
        initrd_args: list[str] = []
        for line in lines:
            code, _ = _code_and_brace_delta(line)
            stripped = code.strip()
            if stripped.startswith("linux ") or stripped.startswith("linuxefi "):
                linux_args = shlex.split(stripped)[1:]
            elif stripped.startswith("initrd ") or stripped.startswith("initrdefi "):
                initrd_args.extend(shlex.split(stripped)[1:])
        if not linux_args or not initrd_args:
            continue
        kernel, *args = linux_args
        ostree_args = [arg.split("=", 1)[1] for arg in args if arg.startswith("ostree=")]
        if len(ostree_args) != 1:
            continue
        ostree = ostree_args[0]
        if ostree == "auto":
            # Deepin's initramfs can resolve ostree=auto using BOOT_IMAGE, but
            # a UKI does not provide GRUB's per-entry BOOT_IMAGE value. Bind
            # this UKI to the deployment encoded in this menu entry's kernel.
            match = re.match(r"^/boot/immutable/([^/]+)/vmlinuz(?:-[^/]*)?$", kernel)
            if match:
                deployment_id = match.group(1)
            else:
                # Some Deepin images expose the current and rollback kernels
                # as /boot/vmlinuz-* while keeping ostree=auto. In that layout
                # the deployment IDs are recorded in status.list, in the same
                # current/rollback order as the generated GRUB entries.
                try:
                    deployment_id = next(auto_deployment_ids)
                except StopIteration as exc:
                    raise ManagerError(
                        f"{title}: ostree=auto 无法从内核路径识别 deployment：{kernel}"
                        "；请提供 /persistent/ostree/data/status.list"
                    ) from exc
            if not re.fullmatch(r"[A-Za-z0-9._-]+", deployment_id):
                raise ManagerError(f"{title}: deployment ID 不安全：{deployment_id}")
            ostree = f"/ostree/data/{deployment_id}/checkout"
            args = [
                f"ostree={ostree}" if arg.startswith("ostree=") else arg
                for arg in args
            ]
        # This value is a GRUB-time variable, unavailable to a UKI. It is a
        # display-mode hint and is intentionally omitted from the UKI cmdline.
        args = [arg for arg in args if arg != "DEEPIN_GFXMODE=$DEEPIN_GFXMODE"]
        if any("$" in arg for arg in args):
            raise ManagerError(f"{title}: 未处理的 GRUB 变量出现在内核参数中")
        entries.append(BootEntry(
            title=title,
            kernel=kernel,
            initrds=tuple(initrd_args),
            cmdline=" ".join(args),
            ostree=ostree,
        ))
    return entries


def _rooted(root: Path, path: str | Path) -> Path:
    candidate = Path(path)
    return root / candidate.relative_to("/") if candidate.is_absolute() else root / candidate


def _read_deployment_list(path: Path) -> list[str]:
    """Read Deepin's data deployment IDs in current/rollback order."""
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except FileNotFoundError:
        return []
    except OSError as exc:
        raise ManagerError(f"无法读取 deployment 列表：{path}: {exc}") from exc

    deployments = [line.strip() for line in lines if line.strip()]
    for deployment_id in deployments:
        if not re.fullmatch(r"[A-Za-z0-9._-]+", deployment_id):
            raise ManagerError(
                f"deployment 列表包含不安全的 ID：{deployment_id}"
            )
    return deployments


def _validate_entry(entry: BootEntry, root: Path) -> tuple[Path, tuple[Path, ...]]:
    if not entry.ostree.startswith("/"):
        raise ManagerError(f"{entry.title}: ostree= 必须是绝对路径")
    if ".." in Path(entry.ostree).parts:
        raise ManagerError(f"{entry.title}: ostree= 路径包含 '..'")
    checkout = _rooted(root, entry.ostree)
    # On Deepin the initramfs-visible /ostree/data path is backed by the
    # persistent partition at /persistent/ostree/data on the running host.
    # Accept either layout so the same code also works in image/test roots.
    match = re.fullmatch(r"/ostree/data/([^/]+)/checkout", entry.ostree)
    if not checkout.is_dir() and match:
        checkout = root / "persistent" / "ostree" / "data" / match.group(1) / "checkout"
    if not checkout.is_dir():
        raise ManagerError(f"{entry.title}: OSTree checkout 不存在：{checkout}")

    files: list[Path] = []
    for grub_path in (entry.kernel, *entry.initrds):
        if not grub_path.startswith("/") or ".." in Path(grub_path).parts:
            raise ManagerError(f"{entry.title}: 不安全的 GRUB 启动路径：{grub_path}")
        host_path = _rooted(root, grub_path)
        if not host_path.is_file() or not os.access(host_path, os.R_OK):
            raise ManagerError(f"{entry.title}: 启动文件不存在或不可读：{host_path}")
        files.append(host_path)
    return files[0], tuple(files[1:])


def _pe_sections(path: Path) -> dict[str, bytes]:
    data = path.read_bytes()
    if len(data) < 0x40 or data[:2] != b"MZ":
        raise ManagerError("ukify 输出不是有效的 EFI/PE 文件")
    pe_offset = int.from_bytes(data[0x3C:0x40], "little")
    if data[pe_offset:pe_offset + 4] != b"PE\0\0":
        raise ManagerError("ukify 输出缺少 PE 签名")
    coff = pe_offset + 4
    section_count = int.from_bytes(data[coff + 2:coff + 4], "little")
    optional_size = int.from_bytes(data[coff + 16:coff + 18], "little")
    section_table = coff + 20 + optional_size
    sections: dict[str, bytes] = {}
    for index in range(section_count):
        pos = section_table + index * 40
        name = data[pos:pos + 8].split(b"\0", 1)[0].decode("ascii", "replace")
        size = int.from_bytes(data[pos + 16:pos + 20], "little")
        offset = int.from_bytes(data[pos + 20:pos + 24], "little")
        sections[name] = data[offset:offset + size]
    return sections


def _validate_osrel_section(data: bytes) -> None:
    payload = data.split(b"\0", 1)[0]
    try:
        content = payload.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ManagerError("UKI 的 .osrel section 不是有效的 UTF-8") from exc

    values = {}
    for line in content.splitlines():
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, value = line.split("=", 1)
        values[key] = value.strip().strip('"')
    if not values.get("ID"):
        raise ManagerError(
            "UKI 的 .osrel section 缺少有效的 ID= 字段；"
            "请确认 ukify 使用 --os-release=@<文件路径>"
        )


def _build_one(
    entry: BootEntry,
    kernel: Path,
    initrds: tuple[Path, ...],
    output_path: Path,
    ukify: str,
    os_release: Path,
    secure_boot_key: Path | None,
    secure_boot_certificate: Path | None,
) -> None:
    cmd = [
        ukify, "build", f"--linux={kernel}",
        f"--cmdline={entry.cmdline}", f"--os-release=@{os_release}",
    ]
    cmd.extend(f"--initrd={initrd}" for initrd in initrds)
    if secure_boot_key or secure_boot_certificate:
        if not secure_boot_key or not secure_boot_certificate:
            raise ManagerError("Secure Boot 签名需要同时提供私钥和证书")
        cmd.extend([
            f"--secureboot-private-key={secure_boot_key}",
            f"--secureboot-certificate={secure_boot_certificate}",
        ])
    cmd.append(f"--output={output_path}")
    subprocess.run(cmd, check=True)

    sections = _pe_sections(output_path)
    missing = {".linux", ".initrd", ".cmdline", ".osrel"} - sections.keys()
    if missing:
        raise ManagerError(f"UKI 缺少必要 PE section：{', '.join(sorted(missing))}")
    _validate_osrel_section(sections[".osrel"])
    embedded_cmdline = sections[".cmdline"].split(b"\0", 1)[0].decode(errors="replace")
    if embedded_cmdline != entry.cmdline:
        raise ManagerError(f"{entry.title}: UKI 中的 .cmdline 与预期不一致")

    os.chmod(output_path, 0o644)
    with output_path.open("rb") as stream:
        os.fsync(stream.fileno())


def _file_digest(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        while chunk := stream.read(1024 * 1024):
            digest.update(chunk)
    return digest.hexdigest()


def _fsync_directory(path: Path) -> None:
    dir_fd = os.open(path, os.O_DIRECTORY)
    try:
        os.fsync(dir_fd)
    finally:
        os.close(dir_fd)


def _publish_pair(staged: dict[str, Path], destination: Path) -> None:
    """Publish current/rollback together, restoring old files on runtime errors.

    FAT does not provide a multi-file atomic rename. This provides rollback for
    detected errors during publication; the backup files are retained if
    restoration itself fails.
    """
    changed: dict[str, Path] = {}
    for name, source in staged.items():
        target = destination / name
        if target.is_file() and _file_digest(source) == _file_digest(target):
            continue
        changed[name] = source

    if not changed:
        print("UKI 未变化，无需替换")
        return

    backup_dir = Path(tempfile.mkdtemp(prefix=".deepin-uki-recovery-", dir=destination))
    had_original: dict[str, bool] = {}
    try:
        for name in changed:
            target = destination / name
            backup = backup_dir / name
            had_original[name] = target.is_file()
            if had_original[name]:
                shutil.copy2(target, backup)
                with backup.open("rb") as stream:
                    os.fsync(stream.fileno())
    except OSError:
        shutil.rmtree(backup_dir, ignore_errors=True)
        raise

    published: list[str] = []
    try:
        for name, source in changed.items():
            os.replace(source, destination / name)
            published.append(name)
        _fsync_directory(destination)
    except OSError as publish_error:
        restore_errors: list[str] = []
        for name in reversed(published):
            target = destination / name
            try:
                if had_original[name]:
                    os.replace(backup_dir / name, target)
                else:
                    target.unlink(missing_ok=True)
            except OSError as restore_error:
                restore_errors.append(f"{name}: {restore_error}")
        try:
            _fsync_directory(destination)
        except OSError as sync_error:
            restore_errors.append(f"目录同步: {sync_error}")
        if restore_errors:
            raise TransactionRecoveryError(
                f"发布失败：{publish_error}；恢复也失败，备份保留在 "
                f"{backup_dir}（" + "; ".join(restore_errors) + ")"
            ) from publish_error
        shutil.rmtree(backup_dir, ignore_errors=True)
        raise ManagerError(
            f"current/rollback UKI 发布失败，旧文件已恢复：{publish_error}"
        ) from publish_error
    shutil.rmtree(backup_dir, ignore_errors=True)


def reconcile(args: argparse.Namespace) -> int:
    root = Path(args.root).resolve()
    config = _rooted(root, args.grub_config)
    destination = _rooted(root, args.uki_dir)
    os_release = _rooted(root, args.os_release)
    status_list = _rooted(root, args.status_list)
    auto_deployments = _read_deployment_list(status_list)
    lock_path = _rooted(root, args.lock_file)
    lock_path.parent.mkdir(parents=True, exist_ok=True)

    with lock_path.open("w") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        if not config.is_file():
            raise ManagerError(f"找不到 GRUB 配置：{config}")
        entries = parse_top_level_entries(
            config.read_text(encoding="utf-8"), auto_deployments
        )
        if len(entries) < 2:
            raise ManagerError(
                "没有找到 current 和 rollback 两个带 linux、initrd、ostree= "
                "参数的顶层菜单项"
            )

        # Deepin's generated GRUB menu puts the current deployment first and
        # the rollback deployment second. Treat this pair as one transaction.
        pair = (entries[0], entries[1])
        if pair[0].deployment_id == pair[1].deployment_id:
            raise ManagerError("current 和 rollback 指向同一个 deployment")

        validated: list[tuple[BootEntry, Path, tuple[Path, ...]]] = []
        for entry in pair:
            kernel, initrds = _validate_entry(entry, root)
            validated.append((entry, kernel, initrds))

        destination.mkdir(parents=True, exist_ok=True)
        with tempfile.TemporaryDirectory(
            prefix=".deepin-uki-transaction-", dir=destination
        ) as transaction_dir_name:
            transaction_dir = Path(transaction_dir_name)
            staged = {
                "deepin-current.efi": transaction_dir / "deepin-current.efi",
                "deepin-rollback.efi": transaction_dir / "deepin-rollback.efi",
            }
            for (entry, kernel, initrds), output in zip(validated, staged.values()):
                _build_one(
                    entry, kernel, initrds, output, args.ukify, os_release,
                    Path(args.secure_boot_key) if args.secure_boot_key else None,
                    Path(args.secure_boot_certificate) if args.secure_boot_certificate else None,
                )

            _publish_pair(staged, destination)

        for role, (entry, _, _) in zip(("current", "rollback"), validated):
            print(
                f"OK {role}: {entry.deployment_id} -> "
                f"{destination / f'deepin-{role}.efi'}"
            )
        return 0


def status(args: argparse.Namespace) -> int:
    directory = _rooted(Path(args.root).resolve(), args.uki_dir)
    if not directory.is_dir():
        print(f"UKI 目录尚不存在：{directory}")
        return 0
    for path in sorted(directory.glob("deepin-*.efi")):
        print(f"{path.stat().st_size:>12}  {path.name}")
    return 0


def make_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="deepin-uki-manager",
        description="从 GRUB 顶层 OSTree 菜单项生成并管理 UKI",
    )
    subparsers = parser.add_subparsers(dest="command", required=True)
    for name, function in (("reconcile", reconcile), ("status", status)):
        sub = subparsers.add_parser(name)
        sub.set_defaults(function=function)
        sub.add_argument("--root", default="/", help="系统根目录（默认 /，主要用于测试）")
        sub.add_argument("--grub-config", default="/boot/grub/grub.cfg")
        sub.add_argument("--uki-dir", default="/boot/xbootldr/EFI/Linux")
        if name == "reconcile":
            sub.add_argument("--ukify", default=shutil.which("ukify") or "ukify")
            sub.add_argument("--os-release", default="/etc/os-release")
            sub.add_argument("--lock-file", default="/run/lock/deepin-uki-manager.lock")
            sub.add_argument(
                "--status-list",
                default="/persistent/ostree/data/status.list",
                help="Deepin data deployment 列表（current/rollback 顺序）",
            )
            sub.add_argument("--secure-boot-key")
            sub.add_argument("--secure-boot-certificate")
    return parser


def main() -> int:
    args = make_parser().parse_args()
    try:
        return args.function(args)
    except (ManagerError, OSError, UnicodeError) as exc:
        print(f"deepin-uki-manager: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
